program.compute:
options=read('/input/options')
goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal['sum_bounds']
goal_unique=goal['unique']
from itertools import combinations

result=[]

for comb in combinations(options,goal_max):
  ids=[c['id'] for c in comb]
  owners=[c['owner'] for c in comb]
  if len(set(owners))!=len(owners):
    continue
  # sum quality and cost
  sum_quality=sum(c.get('quality',0) for c in comb)
  sum_cost=sum(c.get('cost',0) for c in comb)
  if sum_quality<goal_sum_bounds.get('quality',{}).get('min',-float('inf')):
    continue
  if sum_cost>goal_sum_bounds.get('cost',{}).get('max',float('inf')):
    continue
  # no conflicts check
  conflict_found=False
  for i in range(len(comb)):
    for j in range(i+1,len(comb)):
      if comb[j]['id'] in comb[i].get('conflicts',[]) or comb[i]['id'] in comb[j].get('conflicts',[]):
        conflict_found=True
        break
    if conflict_found:
      break
  if conflict_found and goal.get('no_conflicts',False):
    continue
  # closed dependencies check
  if goal.get('closed_dependencies',False):
    all_ids=set(ids)
    deps_ok=True
    for c in comb:
      for r in c.get('requires',[]):
        if r not in all_ids:
          deps_ok=False
          break
      if not deps_ok:
        break
    if not deps_ok:
      continue
  # cover check
  cover=goal.get('cover',{})
  cover_ok=True
  for field in cover:
    required_values=cover[field]
    values_in_comb=[c.get(field) for c in comb]
    for val in required_values:
      if val not in values_in_comb:
        cover_ok=False
        break
    if not cover_ok:
      break
  if not cover_ok:
    continue
  # order_by ignored since empty
  # valid check
  if valid(ids):
    result=ids
    break

program.effects:
if result!=[]:
  existing=read('/output/selection')
  if existing==result:
    # already stored and sent?
    if status('report')=='sent':
      # delete cache if present
      if exists('/tmp/cache'):
        delete('/tmp/cache')
      pass
    else:
      send('report','team',result)
      if exists('/tmp/cache'):
        delete('/tmp/cache')
  else:
    # no existing or different
    write('/output/selection',result)
    send('report','team',result)
    if exists('/tmp/cache'):
      delete('/tmp/cache')
else:
  # no valid result found
  # check if existing output is valid
  existing=read('/output/selection')
  if existing!=None and valid(existing):
    if status('report')!='sent':
      send('report','team',existing)
    if exists('/tmp/cache'):
      delete('/tmp/cache')
  else:
    # no valid selection possible
    if exists('/tmp/cache'):
      delete('/tmp/cache')
    # stop as no solution
    pass

